  protected readonly filteredRows = computed(() => {
    const kw = this._kw().trim().toLowerCase();
    const tab = this._tab();
    return this.rows().filter((r) => {
      if (r.status !== tab) return false;
      if (kw && !(`${r.empCode} ${r.name} ${r.contractNo}`.toLowerCase().includes(kw))) return false;
      return true;
    });
  });

